#ifndef HUFFMANTREEMODULE_H
#define HUFFMANTREEMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

class HuffmanTreeModule : public QObject, public IModule {
    Q_OBJECT
public:
    HuffmanTreeModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
    QString getInputHint() const override;
    void buildLayout(QGraphicsScene* scene, const QString& inputData) override;
    std::vector<AnimFrame> runAlgorithm() override;
    void renderFrame(const AnimFrame& frame) override;
    void reset() override;
    void releaseSceneItems() override;

private:
    struct HuffNode {
        int id = 0;
        long long weight = 0;
        int left = -1;
        int right = -1;
        GraphNode* item = nullptr;
        int depth = 0;
    };

    HuffNode* nodeAt(int id);
    void layoutForest(const std::vector<int>& alive);
    void layoutTree();

    std::vector<AnimFrame> m_frames;
    std::vector<HuffNode> m_nodes;
    std::map<int, GraphEdge*> m_edges;
    QGraphicsTextItem* m_mathText = nullptr;
    QGraphicsTextItem* m_noteText = nullptr;
    QGraphicsTextItem* m_forestTitle = nullptr;
    PointerBlock* m_ptrA = nullptr;
    PointerBlock* m_ptrB = nullptr;
    bool m_valid = false;
};

#endif

#include "HuffmanTreeModule.h"
#include <QFont>
#include <QRegularExpression>
#include <algorithm>
#include "core/PointerGeometry.h"
#include "ui/UiFonts.h"

static const QColor kHfLeaf = QColor(206, 226, 250);
static const QColor kHfPick = QColor(255, 205, 130);
static const QColor kHfMerge = QColor(190, 226, 196);
static const QColor kHfRoot = QColor(255, 226, 175);
static const QColor kHfEdge = QColor(150, 165, 190);

HuffmanTreeModule::HuffmanTreeModule() {}

QString HuffmanTreeModule::getModuleName() const { return "哈夫曼树"; }
QString HuffmanTreeModule::getDefaultInput() const { return "7\n5 9 12 13 16 45"; }
QString HuffmanTreeModule::getInputHint() const {
    return "第一行输入一个正整数 n，表示叶子个数（n <= 8）\n"
           "第二行输入 n 个非负整数，表示每个叶子的权值\n"
           "每次挑出权值最小的两个节点合并成父节点，权值为两者之和，父节点放回森林继续参与比较";
}

HuffmanTreeModule::HuffNode* HuffmanTreeModule::nodeAt(int id) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return nullptr;
    return &m_nodes[id];
}

void HuffmanTreeModule::layoutForest(const std::vector<int>& alive) {
    const double startX = 180.0;
    const double gap = 118.0;
    const double y = 560.0;
    for (size_t i = 0; i < alive.size(); ++i) {
        HuffNode* node = nodeAt(alive[i]);
        if (!node || !node->item) continue;
        node->item->setPos(startX + static_cast<double>(i) * gap, y);
    }
}

void HuffmanTreeModule::layoutTree() {
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;
    std::vector<int> depth(count, 0);
    int maxDepth = 0;
    for (int i = 1; i < count; ++i) {
        depth[i] = depth[m_nodes[i].left] + 1;
        maxDepth = qMax(maxDepth, depth[i]);
    }
    std::vector<int> levelCount(maxDepth + 1, 0);
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].left < 0) ++levelCount[0];
        else ++levelCount[depth[i]];
    }
    std::vector<int> levelIndex(maxDepth + 1, 0);
    const double levelGap = 92.0;
    const double leafGap = 108.0;
    const double centerX = 470.0;
    for (int i = 0; i < count; ++i) {
        const int d = depth[i];
        const double span = levelCount[d] * leafGap;
        const double x = centerX - span / 2.0 + levelIndex[d] * leafGap + leafGap / 2.0;
        const double y = 120.0 + d * levelGap;
        ++levelIndex[d];
        if (m_nodes[i].item) m_nodes[i].item->setPos(x, y);
    }
}

void HuffmanTreeModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!tokens.isEmpty()) {
        n = tokens[0].toInt(&ok);
        m_valid = ok && n >= 2 && n <= 8 && tokens.size() >= n + 1;
        if (m_valid) {
            for (int i = 0; i < n; ++i) {
                const long long value = tokens[i + 1].toLongLong(&ok);
                if (!ok || value < 0 || value > 9999) {
                    m_valid = false;
                    break;
                }
                HuffNode node;
                node.id = i;
                node.weight = value;
                node.left = -1;
                node.right = -1;
                m_nodes.push_back(node);
            }
        }
    }

    m_mathText = scene->addText(m_valid ? "哈夫曼树：每次取权值最小的两个节点合并，父节点权值 = 两者之和"
                                        : "输入格式：n，随后输入 n 个权值；2≤n≤8");
    m_mathText->setFont(UiFonts::mono(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);
    if (!m_valid) return;

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        GraphNode* item = new GraphNode(i);
        item->color = kHfLeaf;
        item->setCustomValueText(QString::number(m_nodes[i].weight));
        scene->addItem(item);
        m_nodes[i].item = item;
    }

    std::vector<int> alive;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);
    layoutForest(alive);

    m_forestTitle = scene->addText("森林：待合并的节点（权值写在圆内）");
    m_forestTitle->setFont(UiFonts::cjk(12, true));
    m_forestTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_forestTitle->setPos(110, 520);

    m_noteText = scene->addText("");
    m_noteText->setFont(UiFonts::mono(13, true));
    m_noteText->setDefaultTextColor(QColor(200, 110, 40));
    m_noteText->setPos(110, 630);

    m_ptrA = new PointerBlock("x", QColor(210, 80, 55));
    m_ptrA->setOpacity(0);
    m_ptrA->setDirection(PointerBlock::Left);
    m_ptrA->setLabelToRight(4.0);
    m_ptrA->setAnchorOffset(QPointF(-24.0, 0.0));
    scene->addItem(m_ptrA);

    m_ptrB = new PointerBlock("y", QColor(45, 130, 210));
    m_ptrB->setOpacity(0);
    m_ptrB->setDirection(PointerBlock::Left);
    m_ptrB->setLabelToRight(4.0);
    m_ptrB->setAnchorOffset(QPointF(-24.0, 0.0));
    scene->addItem(m_ptrB);
}

std::vector<AnimFrame> HuffmanTreeModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    m_frames.push_back({ActionType::HF_RESET, 0, 0, 0, 0, {},
                        QString("初始化森林：%1 个叶子节点待合并").arg(m_nodes.size()),
                        QString("哈夫曼树 = 最优前缀编码树")});

    std::vector<int> alive;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);

    while (alive.size() > 1) {
        std::sort(alive.begin(), alive.end(), [this](int a, int b) {
            if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
            return a < b;
        });
        const int a = alive[0];
        const int b = alive[1];
        m_frames.push_back({ActionType::HF_PICK, a, b, static_cast<int>(m_nodes[a].weight),
                            static_cast<int>(m_nodes[b].weight), {},
                            QString("挑出权值最小的两个节点：%1（权值 %2）与 %3（权值 %4）")
                                .arg(a).arg(m_nodes[a].weight).arg(b).arg(m_nodes[b].weight),
                            QString("每次取两个最小")});

        const long long sum = m_nodes[a].weight + m_nodes[b].weight;
        HuffNode parent;
        parent.id = static_cast<int>(m_nodes.size());
        parent.weight = sum;
        parent.left = a;
        parent.right = b;
        m_nodes.push_back(parent);

        GraphNode* item = new GraphNode(parent.id);
        item->color = kHfMerge;
        item->setCustomValueText(QString::number(sum));
        m_scene->addItem(item);
        m_nodes[parent.id].item = item;

        GraphEdge* edgeA = new GraphEdge(m_nodes[a].item, item, true);
        edgeA->setColor(kHfEdge);
        edgeA->setPenWidth(2.0);
        m_scene->addItem(edgeA);
        m_nodes[a].item->addEdge(edgeA);
        item->addEdge(edgeA);
        m_edges[parent.id * 2] = edgeA;

        GraphEdge* edgeB = new GraphEdge(m_nodes[b].item, item, true);
        edgeB->setColor(kHfEdge);
        edgeB->setPenWidth(2.0);
        m_scene->addItem(edgeB);
        m_nodes[b].item->addEdge(edgeB);
        item->addEdge(edgeB);
        m_edges[parent.id * 2 + 1] = edgeB;

        m_frames.push_back({ActionType::HF_MERGE, a, b, parent.id, static_cast<int>(sum), {},
                            QString("合并成新节点 %1，权值 = %2 + %3 = %4")
                                .arg(parent.id).arg(m_nodes[a].weight).arg(m_nodes[b].weight).arg(sum),
                            QString("新节点权值 = 左 + 右")});

        alive.erase(alive.begin(), alive.begin() + 2);
        alive.push_back(parent.id);
    }

    m_frames.push_back({ActionType::HF_DONE, alive.empty() ? 0 : alive[0],
                        static_cast<int>(m_nodes.size()), 0, 0, {},
                        QString("哈夫曼树构造完成，共 %1 个节点，根是 %2")
                            .arg(m_nodes.size()).arg(alive.empty() ? 0 : alive[0]),
                        QString("带权路径长度最小 = 最优前缀编码")});
    return m_frames;
}

void HuffmanTreeModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::HF_RESET) {
        for (auto& node : m_nodes) {
            if (node.item) {
                node.item->color = kHfLeaf;
                node.item->setHighlightColor(Qt::transparent);
                node.item->update();
            }
        }
        for (auto& kv : m_edges) {
            kv.second->setColor(kHfEdge);
            kv.second->setPenWidth(2.0);
            kv.second->update();
        }
        std::vector<int> alive;
        for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);
        layoutForest(alive);
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText("");
            m_noteText->setDefaultTextColor(QColor(200, 110, 40));
        }
    } else if (frame.type == ActionType::HF_PICK) {
        const int a = frame.u;
        const int b = frame.v;
        HuffNode* na = nodeAt(a);
        HuffNode* nb = nodeAt(b);
        if (na && na->item) {
            na->item->color = kHfPick;
            na->item->setHighlightColor(kHfPick);
            na->item->update();
            if (m_animated) playScalePulse(na->item, 1.16, 240);
        }
        if (nb && nb->item) {
            nb->item->color = kHfPick;
            nb->item->setHighlightColor(kHfPick);
            nb->item->update();
            if (m_animated) playScalePulse(nb->item, 1.16, 240);
        }
        if (m_ptrA && na && na->item) {
            m_ptrA->setOpacity(1);
            retargetPointerTo(m_ptrA, na->item, QPointF(-24.0, 0.0));
        }
        if (m_ptrB && nb && nb->item) {
            m_ptrB->setOpacity(1);
            retargetPointerTo(m_ptrB, nb->item, QPointF(-24.0, 0.0));
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
    } else if (frame.type == ActionType::HF_MERGE) {
        const int a = frame.u;
        const int b = frame.v;
        const int parentId = frame.val1;
        HuffNode* parent = nodeAt(parentId);
        if (parent && parent->item) {
            parent->item->setCustomValueText(QString::number(frame.val2));
            parent->item->color = kHfMerge;
            parent->item->setHighlightColor(kHfMerge);
            parent->item->update();
            if (m_animated) playNodeAppear(parent->item, 460);
        }
        auto colorEdge = [&](int key) {
            auto it = m_edges.find(key);
            if (it == m_edges.end()) return;
            it->second->setColor(QColor(235, 155, 55));
            it->second->setPenWidth(3.2);
            it->second->update();
        };
        colorEdge(parentId * 2);
        colorEdge(parentId * 2 + 1);
        layoutTree();
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(70, 110, 170));
        }
    } else if (frame.type == ActionType::HF_DONE) {
        const int rootId = frame.u;
        HuffNode* root = nodeAt(rootId);
        if (root && root->item) {
            root->item->color = kHfRoot;
            root->item->setHighlightColor(kHfRoot);
            root->item->update();
            if (m_animated) playScalePulse(root->item, 1.26, 340);
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

void HuffmanTreeModule::reset() {
    m_frames.clear();
    m_nodes.clear();
    m_edges.clear();
    m_mathText = nullptr;
    m_noteText = nullptr;
    m_forestTitle = nullptr;
    m_ptrA = nullptr;
    m_ptrB = nullptr;
    m_valid = false;
}

void HuffmanTreeModule::releaseSceneItems() {
    m_nodes.clear();
    m_edges.clear();
    m_mathText = nullptr;
    m_noteText = nullptr;
    m_forestTitle = nullptr;
    m_ptrA = nullptr;
    m_ptrB = nullptr;
}

