#include "HuffmanTreeModule.h"
#include <QFont>
#include <QRegularExpression>
#include <algorithm>
#include "core/PointerGeometry.h"
#include "ui/UiFonts.h"

static const QColor kHfLeaf = QColor(206, 226, 250);
static const QColor kHfLeafSorted = QColor(178, 210, 244);
static const QColor kHfPick = QColor(255, 205, 130);
static const QColor kHfMerge = QColor(190, 226, 196);
static const QColor kHfRoot = QColor(255, 226, 175);
static const QColor kHfEdge = QColor(150, 165, 190);
static const QColor kHfEdgeNew = QColor(226, 142, 44);

HuffmanTreeModule::HuffmanTreeModule() {}

QString HuffmanTreeModule::getModuleName() const { return "哈夫曼树"; }
QString HuffmanTreeModule::getDefaultInput() const { return "7\n5 9 12 13 16 45 20"; }
QString HuffmanTreeModule::getInputHint() const {
    return "第一行输入一个正整数 n，表示叶子个数（2 <= n <= 8）\n"
           "第二行输入 n 个非负整数，表示每个叶子的权值\n"
           "先对权值数组升序排序，再每次取两个最小权值合并成父节点，父节点权值 = 两者之和";
}

HuffmanTreeModule::HuffNode* HuffmanTreeModule::nodeAt(int id) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return nullptr;
    return &m_nodes[id];
}

void HuffmanTreeModule::layoutArray() {
    for (size_t i = 0; i < m_arrayCells.size(); ++i) {
        if (m_arrayCells[i]) {
            m_arrayCells[i]->setPos(kArrayLeft + static_cast<double>(i) * kCellW, kArrayY);
        }
    }
}

void HuffmanTreeModule::layoutForest() {
    const int count = static_cast<int>(m_nodes.size());
    const double gap = 128.0;
    const double left = 170.0;
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].item) {
            m_nodes[i].item->setPos(left + static_cast<double>(i) * gap, kForestY);
        }
    }
}

void HuffmanTreeModule::computeDepths() {
    const int count = static_cast<int>(m_nodes.size());
    for (int i = 0; i < count; ++i) m_nodes[i].depth = 0;
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].parent < 0) continue;
        m_nodes[i].depth = m_nodes[m_nodes[i].parent].depth + 1;
    }
}

void HuffmanTreeModule::assignRowsAndCols() {
    computeDepths();
    int maxDepth = 0;
    for (const HuffNode& node : m_nodes) maxDepth = qMax(maxDepth, node.depth);
    m_maxDepth = maxDepth;

    std::vector<std::vector<int>> byDepth(maxDepth + 1);
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        byDepth[m_nodes[i].depth].push_back(i);
    }

    for (int d = 0; d <= maxDepth; ++d) {
        std::vector<int>& row = byDepth[d];
        std::sort(row.begin(), row.end(), [this](int a, int b) {
            if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
            return a < b;
        });
        for (size_t k = 0; k < row.size(); ++k) {
            m_nodes[row[k]].row = d;
            m_nodes[row[k]].col = static_cast<int>(k);
        }
    }
}

void HuffmanTreeModule::computeTargets() {
    m_targets.clear();
    if (!m_sortDone) {
        for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
            m_targets[i] = QPointF(kArrayLeft + i * kCellW, kArrayY);
        }
        return;
    }

    assignRowsAndCols();
    int maxNodesInRow = 1;
    for (const HuffNode& node : m_nodes) maxNodesInRow = qMax(maxNodesInRow, node.col + 1);
    m_maxNodesInRow = maxNodesInRow;

    const double span = maxNodesInRow * kLeafGap;
    const double centerX = 430.0;
    for (const HuffNode& node : m_nodes) {
        const double x = centerX - span / 2.0 + node.col * kLeafGap + kLeafGap / 2.0;
        const double y = kTreeTop + node.row * kLevelH;
        m_targets[node.id] = QPointF(x, y);
    }
}

void HuffmanTreeModule::applyTargets(bool animate) {
    if (m_targets.empty()) return;
    std::vector<QGraphicsItem*> movers;
    std::vector<QPointF> deltas;
    for (auto& kv : m_targets) {
        HuffNode* node = nodeAt(kv.first);
        if (!node || !node->item) continue;
        const QPointF delta = kv.second - node->item->pos();
        if (qFuzzyIsNull(delta.x()) && qFuzzyIsNull(delta.y())) continue;
        movers.push_back(node->item);
        deltas.push_back(delta);
    }
    if (movers.empty()) return;

    if (!animate) {
        for (size_t i = 0; i < movers.size(); ++i) {
            movers[i]->setPos(movers[i]->pos() + deltas[i]);
        }
        return;
    }

    for (size_t i = 0; i < movers.size(); ++i) {
        QGraphicsItem* item = movers[i];
        const QPointF delta = deltas[i];
        QVariantAnimation* anim = new QVariantAnimation(item);
        anim->setDuration(440);
        anim->setStartValue(0.0);
        anim->setEndValue(1.0);
        anim->setEasingCurve(QEasingCurve::InOutCubic);
        const QPointF start = item->pos();
        QObject::connect(anim, &QVariantAnimation::valueChanged, [item, start, delta](const QVariant& v) {
            const qreal t = v.toReal();
            if (item) item->setPos(start + delta * t);
        });
        anim->start(QAbstractAnimation::DeleteWhenStopped);
    }
}

void HuffmanTreeModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!tokens.isEmpty()) {
        n = tokens[0].toInt(&ok);
        m_valid = ok && n >= 2 && n <= 8 && tokens.size() >= n + 1;
        if (m_valid) {
            for (int i = 0; i < n; ++i) {
                const long long value = tokens[i + 1].toLongLong(&ok);
                if (!ok || value < 0 || value > 9999) {
                    m_valid = false;
                    break;
                }
                HuffNode node;
                node.id = i;
                node.weight = value;
                node.original = true;
                m_nodes.push_back(node);
            }
        }
    }

    m_mathText = scene->addText(m_valid ? "哈夫曼树：每次取权值最小的两个节点合并，父节点权值 = 两者之和"
                                        : "输入格式：n，随后输入 n 个权值；2 <= n <= 8");
    m_mathText->setFont(UiFonts::mixed(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);
    if (!m_valid) return;

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        ArrayBlock* cell = new ArrayBlock(i, 0, QString::number(i));
        cell->setCellSize(kCellW, kCellH);
        cell->setShowLabel(false);
        cell->color = kHfLeaf;
        cell->setCustomValue(QString::number(m_nodes[i].weight));
        cell->setValueFontSize(14);
        cell->setPos(kArrayLeft + static_cast<double>(i) * kCellW, kArrayY);
        scene->addItem(cell);
        m_arrayCells.push_back(cell);
    }

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        GraphNode* item = new GraphNode(i);
        item->color = kHfLeaf;
        item->setCustomValueText(QString::number(m_nodes[i].weight));
        scene->addItem(item);
        m_nodes[i].item = item;
    }
    layoutForest();

    m_arrayTitle = scene->addText("频率数组 a[]");
    m_arrayTitle->setFont(UiFonts::cjk(12, true));
    m_arrayTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_arrayTitle->setPos(kArrayLeft - 30, kArrayY - 28);

    m_phaseText = scene->addText("阶段一：把频率数组升序排序");
    m_phaseText->setFont(UiFonts::cjk(13, true));
    m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
    m_phaseText->setPos(110, 84);

    m_noteText = scene->addText("");
    m_noteText->setFont(UiFonts::mixed(13, true));
    m_noteText->setDefaultTextColor(QColor(200, 110, 40));
    m_noteText->setPos(110, 700);

    m_ptrA = new PointerBlock("x", QColor(210, 80, 55));
    m_ptrA->setOpacity(0);
    m_ptrA->setDirection(PointerBlock::Down);
    m_ptrA->setShaftLength(22);
    m_ptrA->setAnchorOffset(PointerGeometry::aboveCell(kCellW, kCellH));
    m_ptrA->setLabelAtTail(6.0);
    scene->addItem(m_ptrA);

    m_ptrB = new PointerBlock("y", QColor(45, 130, 210));
    m_ptrB->setOpacity(0);
    m_ptrB->setDirection(PointerBlock::Down);
    m_ptrB->setShaftLength(22);
    m_ptrB->setAnchorOffset(PointerGeometry::aboveCell(kCellW, kCellH));
    m_ptrB->setLabelAtTail(6.0);
    scene->addItem(m_ptrB);
}

std::vector<AnimFrame> HuffmanTreeModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    m_frames.push_back({ActionType::HF_RESET, 0, 0, 0, 0, {},
                        QString("频率数组 a[]：%1 个权值待排序").arg(m_nodes.size()),
                        QString("哈夫曼树 = 最优前缀编码树")});

    std::vector<long long> weights;
    for (const HuffNode& node : m_nodes) weights.push_back(node.weight);

    std::vector<int> slots;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) slots.push_back(i);

    std::vector<long long> sorted = weights;
    std::sort(sorted.begin(), sorted.end());

    for (int step = 0; step < static_cast<int>(slots.size()); ++step) {
        int cur = 0;
        while (cur < static_cast<int>(slots.size()) && slots[cur] != step) ++cur;
        if (cur >= static_cast<int>(slots.size()) || cur == step) continue;

        for (int j = 0; j < static_cast<int>(slots.size()); ++j) {
            if (slots[j] == step) continue;
            m_frames.push_back({ActionType::HF_SORT_LIFT, step, slots[j],
                                static_cast<int>(weights[slots[j]]), 0, {step, cur},
                                QString("a[%1] = %2 不在排序后应在的位置，先飞出数组")
                                    .arg(slots[j]).arg(weights[slots[j]]),
                                QString("不在应有位置的元素先飞出")});
        }

        const int moved = slots[cur];
        slots.erase(slots.begin() + cur);
        slots.insert(slots.begin(), step);
        m_frames.push_back({ActionType::HF_SORT_DROP, step, moved,
                            static_cast<int>(weights[moved]), 0, slots,
                            QString("a[%1] = %2 像流星一样飞回第 %3 个位置")
                                .arg(moved).arg(weights[moved]).arg(step),
                            QString("飞星落位")});
    }

    QStringList sortedText;
    for (long long w : sorted) sortedText << QString::number(w);
    m_frames.push_back({ActionType::HF_SORT_DONE, 0, 0, 0, 0, {},
                        QString("频率数组排序完成：%1").arg(sortedText.join(" < ")),
                        QString("阶段一完成，进入建树阶段")});

    m_frames.push_back({ActionType::HF_RESET, 1, 0, 0, 0, {},
                        QString("阶段二：开始建树，每次从数组中取两个最小权值"),
                        QString("阶段二：建树")});

    std::vector<int> alive;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);

    while (alive.size() > 1) {
        std::sort(alive.begin(), alive.end(), [this](int a, int b) {
            if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
            return a < b;
        });
        const int a = alive[0];
        const int b = alive[1];

        const bool aOriginal = m_nodes[a].original;
        const bool bOriginal = m_nodes[b].original;
        const int kind = (aOriginal && bOriginal) ? 0 : ((aOriginal != bOriginal) ? 1 : 2);
        const QString kindText = kind == 0
                                     ? "两个都是原始数据，直接作为叶子连到父节点"
                                     : (kind == 1 ? "其中一个已带子树，让另一个飞过去与它相连"
                                                  : "两个都带子树，先把树高调整到同一行再相连");

        m_frames.push_back({ActionType::HF_PICK, a, b, static_cast<int>(m_nodes[a].weight),
                            static_cast<int>(m_nodes[b].weight), {kind},
                            QString("取出两个最小权值：%1（%2）与 %3（%4）；%5")
                                .arg(a).arg(m_nodes[a].weight).arg(b).arg(m_nodes[b].weight).arg(kindText),
                            QString("每次取两个最小")});

        m_frames.push_back({ActionType::HF_LIFT, a, b, static_cast<int>(m_nodes[a].weight),
                            static_cast<int>(m_nodes[b].weight), {kind},
                            kind == 0
                                ? QString("%1 与 %2 一起飞向汇合点，准备作为叶子连接")
                                    .arg(m_nodes[a].weight).arg(m_nodes[b].weight)
                                : QString("带子树的一方上移，准备与 %1 相连").arg(m_nodes[b].weight),
                            QString("飞到一起")});

        const long long sum = m_nodes[a].weight + m_nodes[b].weight;
        HuffNode parent;
        parent.id = static_cast<int>(m_nodes.size());
        parent.weight = sum;
        parent.left = a;
        parent.right = b;
        parent.original = false;
        m_nodes.push_back(parent);

        GraphNode* item = new GraphNode(parent.id);
        item->color = kHfMerge;
        item->setCustomValueText(QString::number(sum));
        m_scene->addItem(item);
        m_nodes[parent.id].item = item;
        m_nodes[a].parent = parent.id;
        m_nodes[b].parent = parent.id;

        GraphEdge* edgeA = new GraphEdge(m_nodes[a].item, item, true);
        edgeA->setColor(kHfEdgeNew);
        edgeA->setPenWidth(2.6);
        m_scene->addItem(edgeA);
        m_nodes[a].item->addEdge(edgeA);
        item->addEdge(edgeA);
        m_childEdges[parent.id * 2] = edgeA;

        GraphEdge* edgeB = new GraphEdge(m_nodes[b].item, item, true);
        edgeB->setColor(kHfEdgeNew);
        edgeB->setPenWidth(2.6);
        m_scene->addItem(edgeB);
        m_nodes[b].item->addEdge(edgeB);
        item->addEdge(edgeB);
        m_childEdges[parent.id * 2 + 1] = edgeB;

        m_frames.push_back({ActionType::HF_MERGE, a, b, parent.id, static_cast<int>(sum), {kind},
                            QString("合并成新节点 %1：%2 + %3 = %4")
                                .arg(parent.id).arg(m_nodes[a].weight).arg(m_nodes[b].weight).arg(sum),
                            QString("新节点权值 = 左 + 右")});

        alive.erase(alive.begin(), alive.begin() + 2);
        alive.push_back(parent.id);
    }

    m_frames.push_back({ActionType::HF_DONE, alive.empty() ? 0 : alive[0],
                        static_cast<int>(m_nodes.size()), 0, 0, {},
                        QString("哈夫曼树构造完成：共 %1 个节点，根节点权值 = %2")
                            .arg(m_nodes.size()).arg(alive.empty() ? 0 : m_nodes[alive[0]].weight),
                        QString("带权路径长度最小 = 最优前缀编码")});
    return m_frames;
}

void HuffmanTreeModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::HF_RESET) {
        m_sortDone = frame.u == 1;
        for (auto& node : m_nodes) {
            if (node.item) {
                node.item->color = node.original ? kHfLeaf : kHfMerge;
                node.item->setHighlightColor(Qt::transparent);
                node.item->update();
            }
        }
        for (auto& kv : m_childEdges) {
            kv.second->setColor(kHfEdge);
            kv.second->setPenWidth(2.0);
            kv.second->update();
        }
        for (auto* cell : m_arrayCells) {
            cell->color = m_sortDone ? kHfLeafSorted : kHfLeaf;
            cell->update();
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText("");
            m_noteText->setDefaultTextColor(QColor(200, 110, 40));
        }
        if (m_sortDone) {
            m_phaseText->setPlainText("阶段二：每次从数组中取两个最小权值合并建树");
            m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
        } else {
            m_phaseText->setPlainText("阶段一：把频率数组升序排序");
            m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
        }
        return;
    }

    if (frame.type == ActionType::HF_SORT_LIFT) {
        const int nodeId = frame.v;
        ArrayBlock* cell = (nodeId >= 0 && nodeId < static_cast<int>(m_arrayCells.size()))
                               ? m_arrayCells[nodeId] : nullptr;
        if (cell) {
            cell->color = kHfPick;
            cell->update();
            if (m_animated) playScalePulse(cell, 1.18, 240);
        }
        if (m_ptrA && cell) {
            m_ptrA->setOpacity(1);
            retargetPointerTo(m_ptrA, cell, PointerGeometry::aboveCell(kCellW, kCellH));
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_SORT_DROP) {
        const int slot = frame.u;
        const int nodeId = frame.v;
        const std::vector<int>& perm = frame.group;
        if (perm.size() != m_arrayCells.size()) return;

        for (size_t i = 0; i < perm.size(); ++i) {
            ArrayBlock* cell = m_arrayCells[i];
            const int id = perm[i];
            if (id >= 0 && id < static_cast<int>(m_nodes.size())) {
                cell->setCustomValue(QString::number(m_nodes[id].weight));
            }
            cell->color = (static_cast<int>(i) == slot) ? kHfLeafSorted : kHfLeaf;
            cell->update();
        }

        ArrayBlock* dest = (slot >= 0 && slot < static_cast<int>(m_arrayCells.size()))
                               ? m_arrayCells[slot] : nullptr;
        if (dest && m_animated) {
            const QPointF start = QPointF(dest->pos().x() + kCellW / 2.0, kArrayY - 76.0);
            const long long weight = (nodeId >= 0 && nodeId < static_cast<int>(m_nodes.size()))
                                         ? m_nodes[nodeId].weight : 0;
            playBubbleFlight(start, dest->pos(), static_cast<int>(weight), 520);
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_SORT_DONE) {
        for (auto* cell : m_arrayCells) {
            cell->color = kHfLeafSorted;
            cell->update();
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
        return;
    }

    if (frame.type == ActionType::HF_PICK) {
        const int a = frame.u;
        const int b = frame.v;
        HuffNode* na = nodeAt(a);
        HuffNode* nb = nodeAt(b);
        if (na && na->item) {
            na->item->color = kHfPick;
            na->item->setHighlightColor(kHfPick);
            na->item->update();
            if (m_animated) playScalePulse(na->item, 1.16, 240);
        }
        if (nb && nb->item) {
            nb->item->color = kHfPick;
            nb->item->setHighlightColor(kHfPick);
            nb->item->update();
            if (m_animated) playScalePulse(nb->item, 1.16, 240);
        }
        if (m_ptrA && na && na->item) {
            m_ptrA->setOpacity(1);
            retargetPointerTo(m_ptrA, na->item, QPointF(0.0, -(kNodeR + 30.0)));
        }
        if (m_ptrB && nb && nb->item) {
            m_ptrB->setOpacity(1);
            retargetPointerTo(m_ptrB, nb->item, QPointF(0.0, -(kNodeR + 30.0)));
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_LIFT) {
        const int a = frame.u;
        const int b = frame.v;
        HuffNode* na = nodeAt(a);
        HuffNode* nb = nodeAt(b);
        if (na && na->item) {
            na->item->setHighlightColor(kHfPick);
            na->item->update();
            if (m_animated) playScalePulse(na->item, 1.24, 320);
        }
        if (nb && nb->item) {
            nb->item->setHighlightColor(kHfPick);
            nb->item->update();
            if (m_animated) playScalePulse(nb->item, 1.24, 320);
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_MERGE) {
        const int parentId = frame.val1;
        HuffNode* parent = nodeAt(parentId);
        if (parent && parent->item) {
            parent->item->setCustomValueText(QString::number(frame.val2));
            parent->item->color = kHfMerge;
            parent->item->setHighlightColor(kHfMerge);
            parent->item->update();
            if (m_animated) playNodeAppear(parent->item, 460);
        }
        auto colorEdge = [&](int key) {
            auto it = m_childEdges.find(key);
            if (it == m_childEdges.end()) return;
            it->second->setColor(kHfEdgeNew);
            it->second->setPenWidth(2.6);
            it->second->update();
        };
        colorEdge(parentId * 2);
        colorEdge(parentId * 2 + 1);

        computeTargets();
        applyTargets(true);

        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(70, 110, 170));
        }
        return;
    }

    if (frame.type == ActionType::HF_DONE) {
        const int rootId = frame.u;
        HuffNode* root = nodeAt(rootId);
        if (root && root->item) {
            root->item->color = kHfRoot;
            root->item->setHighlightColor(kHfRoot);
            root->item->update();
            if (m_animated) playScalePulse(root->item, 1.26, 340);
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        m_phaseText->setPlainText("阶段二完成：哈夫曼树构造结束");
        m_phaseText->setDefaultTextColor(QColor(40, 140, 70));
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

void HuffmanTreeModule::reset() {
    m_frames.clear();
    m_nodes.clear();
    m_arrayCells.clear();
    m_childEdges.clear();
    m_targets.clear();
    m_mathText = nullptr;
    m_noteText = nullptr;
    m_phaseText = nullptr;
    m_arrayTitle = nullptr;
    m_ptrA = nullptr;
    m_ptrB = nullptr;
    m_valid = false;
    m_sortDone = false;
    m_maxDepth = 0;
    m_maxNodesInRow = 1;
}

void HuffmanTreeModule::releaseSceneItems() {
    m_nodes.clear();
    m_arrayCells.clear();
    m_childEdges.clear();
    m_targets.clear();
    m_mathText = nullptr;
    m_noteText = nullptr;
    m_phaseText = nullptr;
    m_arrayTitle = nullptr;
    m_ptrA = nullptr;
    m_ptrB = nullptr;
}

