void HuffmanTreeModule::computeLayout() {
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        node->level = 0;
    }
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node || node->parent < 0) continue;
        HuffNode* p = nodeAt(node->parent);
        if (p) node->level = p->level + 1;
    }

    int minLevel = 0, maxLevel = 0;
    bool first = true;
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        if (first) {
            minLevel = maxLevel = node->level;
            first = false;
        } else {
            minLevel = qMin(minLevel, node->level);
            maxLevel = qMax(maxLevel, node->level);
        }
    }
    m_levelMin = minLevel;
    m_levelMax = maxLevel;

    std::vector<std::vector<int>> rows(maxLevel - minLevel + 1);
    for (auto& kv : m_treeNodes) {
        HuffNode* node = nodeAt(kv.first);
        if (!node) continue;
        rows[node->level - minLevel].push_back(node->id);
    }
    for (auto& row : rows) {
        std::sort(row.begin(), row.end(), [this](int a, int b) {
            const HuffNode* na = nodeAt(a);
            const HuffNode* nb = nodeAt(b);
            if (!na || !nb) return a < b;
            if (na->weight != nb->weight) return na->weight < nb->weight;
            return a < b;
        });
    }

    m_nextPositions.clear();
    std::vector<double> rowX(rows.size(), 0.0);
    std::vector<double> rowWidth(rows.size(), 0.0);
    for (size_t r = 0; r < rows.size(); ++r) {
        const int count = static_cast<int>(rows[r].size());
        rowWidth[r] = count * kBaseGap;
        if (count == 0) continue;
        rowX[r] = kTreeCenterX - rowWidth[r] / 2.0 + kBaseGap / 2.0;
        for (size_t k = 0; k < rows[r].size(); ++k) {
            const int id = rows[r][k];
            m_nextPositions[id] = QPointF(rowX[r] + static_cast<double>(k) * kBaseGap,
                                         kTreeBottom - static_cast<double>(r) * kLevelH);
        }
    }

    for (int pass = 0; pass < 3; ++pass) {
        for (size_t r = 0; r < rows.size(); ++r) {
            for (int id : rows[r]) {
                HuffNode* node = nodeAt(id);
                if (!node) continue;
                const double selfX = m_nextPositions[id].x();
                const double leftX = (node->left >= 0 && m_nextPositions.count(node->left))
                                         ? m_nextPositions[node->left].x() : selfX;
                const double rightX = (node->right >= 0 && m_nextPositions.count(node->right))
                                          ? m_nextPositions[node->right].x() : selfX;
                const double midX = (leftX + rightX) / 2.0;
                const double shifted = selfX + (midX - selfX) * 0.6;
                m_nextPositions[id] = QPointF(shifted, m_nextPositions[id].y());
            }
        }
    }
}

