#ifndef HUFFMANTREEMODULE_H
#define HUFFMANTREEMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

class HuffmanTreeModule : public QObject, public IModule {
    Q_OBJECT
public:
    HuffmanTreeModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
    QString getInputHint() const override;
    void buildLayout(QGraphicsScene* scene, const QString& inputData) override;
    std::vector<AnimFrame> runAlgorithm() override;
    void renderFrame(const AnimFrame& frame) override;
    void reset() override;
    void releaseSceneItems() override;

private:
    struct HuffNode {
        int id = 0;
        long long weight = 0;
        int left = -1;
        int right = -1;
        int parent = -1;
        bool original = true;
        int row = 0;
        int leafSlot = 0;
        GraphNode* item = nullptr;
    };

    struct MergeStep {
        int a = 0;
        int b = 0;
        int parent = 0;
        int kind = 0;
    };

    static constexpr double kNodeR = 20.0;
    static constexpr double kCellW = 76.0;
    static constexpr double kCellH = 46.0;
    static constexpr double kArrayY = 118.0;
    static constexpr double kArrayLeft = 152.0;
    static constexpr double kTreeBottom = 720.0;
    static constexpr double kLevelH = 74.0;
    static constexpr double kBaseGap = 88.0;
    static constexpr double kTreeCenterX = 430.0;

    HuffNode* nodeAt(int id);
    void computePlan();
    void assignLeafSlots();
    void shiftSubtreeRows(int root, int delta);
    void applyMergeRows(int a, int b, int parent);
    void computePositions();
    void applyPositions(int duration);
    void moveSubtreeTo(int root, QPointF goal, int duration);
    void revealLeaves();
    void refreshArrayColors();

    std::vector<AnimFrame> m_frames;
    std::vector<HuffNode> m_nodes;
    std::vector<MergeStep> m_plan;
    std::vector<int> m_leafOrder;
    std::vector<ArrayBlock*> m_arrayCells;
    std::map<int, GraphNode*> m_treeNodes;
    std::map<int, GraphEdge*> m_childEdges;
    std::map<int, QPointF> m_targets;

    QGraphicsTextItem* m_mathText = nullptr;
    QGraphicsTextItem* m_noteText = nullptr;
    QGraphicsTextItem* m_phaseText = nullptr;
    QGraphicsTextItem* m_resultText = nullptr;
    QGraphicsTextItem* m_arrayTitle = nullptr;

    PointerBlock* m_ptrA = nullptr;
    PointerBlock* m_ptrB = nullptr;
    bool m_valid = false;
    bool m_phaseTwo = false;
    int m_usedCount = 0;
};

#endif

#include "HuffmanTreeModule.h"
#include <QFont>
#include <QRegularExpression>
#include <algorithm>
#include "core/PointerGeometry.h"
#include "ui/UiFonts.h"

static const QColor kHfLeaf = QColor(206, 226, 250);
static const QColor kHfSorted = QColor(174, 208, 244);
static const QColor kHfPick = QColor(255, 205, 130);
static const QColor kHfMerge = QColor(190, 226, 196);
static const QColor kHfRoot = QColor(255, 226, 175);
static const QColor kHfEdge = QColor(152, 168, 192);
static const QColor kHfEdgeNew = QColor(224, 138, 40);
static const QColor kHfEmpty = QColor(240, 242, 246);

HuffmanTreeModule::HuffmanTreeModule() {}

QString HuffmanTreeModule::getModuleName() const { return "哈夫曼树"; }
QString HuffmanTreeModule::getDefaultInput() const { return "7\n5 9 12 13 16 45 20"; }
QString HuffmanTreeModule::getInputHint() const {
    return "第一行输入一个正整数 n，表示叶子个数（2 <= n <= 8）\n"
           "第二行输入 n 个非负整数，表示每个叶子的权值\n"
           "先对权值数组升序排序，再每次取两个最小权值合并成父节点，父节点权值 = 两者之和";
}

HuffmanTreeModule::HuffNode* HuffmanTreeModule::nodeAt(int id) {
    if (id < 0 || id >= static_cast<int>(m_nodes.size())) return nullptr;
    return &m_nodes[id];
}

void HuffmanTreeModule::assignLeafSlots() {
    m_leafOrder.clear();
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        if (m_nodes[i].original) m_leafOrder.push_back(i);
    }
    std::sort(m_leafOrder.begin(), m_leafOrder.end(), [this](int a, int b) {
        if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
        return a < b;
    });
    for (size_t k = 0; k < m_leafOrder.size(); ++k) {
        m_nodes[m_leafOrder[k]].leafSlot = static_cast<int>(k);
    }
}

void HuffmanTreeModule::shiftSubtreeRows(int root, int delta) {
    if (root < 0 || delta == 0) return;
    std::vector<int> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        const int id = stack.back();
        stack.pop_back();
        HuffNode* node = nodeAt(id);
        if (!node) continue;
        node->row += delta;
        if (node->left >= 0) stack.push_back(node->left);
        if (node->right >= 0) stack.push_back(node->right);
    }
}

void HuffmanTreeModule::computePlan() {
    m_plan.clear();
    std::vector<int> alive;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);

    while (alive.size() > 1) {
        std::sort(alive.begin(), alive.end(), [this](int a, int b) {
            if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
            return a < b;
        });
        const int a = alive[0];
        const int b = alive[1];
        const bool aOriginal = m_nodes[a].original;
        const bool bOriginal = m_nodes[b].original;
        const int kind = (aOriginal && bOriginal) ? 0 : ((aOriginal != bOriginal) ? 1 : 2);

        HuffNode parent;
        parent.id = static_cast<int>(m_nodes.size());
        parent.weight = m_nodes[a].weight + m_nodes[b].weight;
        parent.left = a;
        parent.right = b;
        parent.original = false;
        m_nodes.push_back(parent);
        m_nodes[a].parent = parent.id;
        m_nodes[b].parent = parent.id;

        MergeStep step;
        step.a = a;
        step.b = b;
        step.parent = parent.id;
        step.kind = kind;
        m_plan.push_back(step);

        alive.erase(alive.begin(), alive.begin() + 2);
        alive.push_back(parent.id);
    }
}

void HuffmanTreeModule::applyMergeRows(int a, int b, int parent) {
    HuffNode* pa = nodeAt(a);
    HuffNode* pb = nodeAt(b);
    HuffNode* pp = nodeAt(parent);
    if (!pa || !pb || !pp) return;

    const int baseRow = qMax(pa->row, pb->row);
    if (pa->row != pb->row) {
        const int lower = qMin(pa->row, pb->row);
        const int upper = qMax(pa->row, pb->row);
        HuffNode* lowNode = (pa->row == lower) ? pa : pb;
        HuffNode* highNode = (pa->row == lower) ? pb : pa;
        const int delta = upper - lower;
        shiftSubtreeRows(highNode->id, delta);
        shiftSubtreeRows(lowNode->id, delta);
    }
    pa->row = baseRow + 1;
    pb->row = baseRow + 1;
    pp->row = baseRow;
}

void HuffmanTreeModule::computePositions() {
    m_targets.clear();
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;

    int maxRow = 0;
    for (const HuffNode& node : m_nodes) maxRow = qMax(maxRow, node.row);

    for (int id = 0; id < count; ++id) {
        const HuffNode& node = m_nodes[id];
        const double y = kTreeBottom - static_cast<double>(node.row) * kLevelH;
        double x = 0.0;
        if (node.original) {
            const double left = kTreeCenterX - (static_cast<double>(m_leafOrder.size()) - 1) * kBaseGap / 2.0;
            x = left + node.leafSlot * kBaseGap;
        } else {
            const HuffNode* l = nodeAt(node.left);
            const HuffNode* r = nodeAt(node.right);
            const double lx = l ? m_targets.count(l->id) ? m_targets[l->id].x() : 0.0 : 0.0;
            const double rx = r ? m_targets.count(r->id) ? m_targets[r->id].x() : 0.0 : 0.0;
            x = (lx + rx) / 2.0;
        }
        m_targets[id] = QPointF(x, y);
    }
}

void HuffmanTreeModule::applyPositions(int duration) {
    std::vector<QGraphicsItem*> movers;
    std::vector<QPointF> goals;
    for (auto& kv : m_targets) {
        auto it = m_treeNodes.find(kv.first);
        if (it == m_treeNodes.end() || !it->second) continue;
        movers.push_back(it->second);
        goals.push_back(kv.second);
    }
    if (movers.empty()) return;
    playMoveTo(movers, goals, duration);
}

void HuffmanTreeModule::moveSubtreeTo(int root, QPointF goal, int duration) {
    std::vector<QGraphicsItem*> movers;
    std::vector<QPointF> goals;
    std::vector<int> stack;
    stack.push_back(root);
    while (!stack.empty()) {
        const int id = stack.back();
        stack.pop_back();
        auto it = m_treeNodes.find(id);
        if (it != m_treeNodes.end() && it->second) {
            movers.push_back(it->second);
            const QPointF target = m_targets.count(id) ? m_targets[id] : goal;
            goals.push_back(QPointF(target.x(), goal.y()));
        }
        HuffNode* node = nodeAt(id);
        if (!node) continue;
        if (node->left >= 0) stack.push_back(node->left);
        if (node->right >= 0) stack.push_back(node->right);
    }
    if (movers.empty()) return;
    playMoveTo(movers, goals, duration);
}

void HuffmanTreeModule::refreshArrayColors() {
    for (size_t i = 0; i < m_arrayCells.size(); ++i) {
        ArrayBlock* cell = m_arrayCells[i];
        if (!cell) continue;
        if (i < m_usedCount) {
            cell->color = kHfSorted;
        } else {
            cell->color = kHfEmpty;
        }
        cell->update();
    }
}

void HuffmanTreeModule::buildLayout(QGraphicsScene* scene, const QString& inputData) {
    m_scene = scene;
    reset();
    m_scene = scene;

    const QStringList tokens = inputData.split(QRegularExpression("\\s+"), Qt::SkipEmptyParts);
    bool ok = false;
    int n = 0;
    if (!tokens.isEmpty()) {
        n = tokens[0].toInt(&ok);
        m_valid = ok && n >= 2 && n <= 8 && tokens.size() >= n + 1;
        if (m_valid) {
            for (int i = 0; i < n; ++i) {
                const long long value = tokens[i + 1].toLongLong(&ok);
                if (!ok || value < 0 || value > 9999) {
                    m_valid = false;
                    break;
                }
                HuffNode node;
                node.id = i;
                node.weight = value;
                node.original = true;
                node.row = 0;
                node.leafSlot = i;
                m_nodes.push_back(node);
            }
        }
    }

    m_mathText = scene->addText(m_valid ? "哈夫曼树：每次取权值最小的两个节点合并，父节点权值 = 两者之和"
                                        : "输入格式：n，随后输入 n 个权值；2 <= n <= 8");
    m_mathText->setFont(UiFonts::mixed(15, true));
    m_mathText->setDefaultTextColor(QColor(40, 70, 110));
    m_mathText->setPos(110, 18);
    if (!m_valid) return;

    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) {
        ArrayBlock* cell = new ArrayBlock(i, 0, QString::number(i));
        cell->setCellSize(kCellW, kCellH);
        cell->setShowLabel(false);
        cell->color = kHfLeaf;
        cell->setCustomValue(QString::number(m_nodes[i].weight));
        cell->setValueFontSize(14);
        cell->setPos(kArrayLeft + static_cast<double>(i) * kCellW, kArrayY);
        scene->addItem(cell);
        m_arrayCells.push_back(cell);
    }

    m_arrayTitle = scene->addText("频率数组 a[]");
    m_arrayTitle->setFont(UiFonts::cjk(12, true));
    m_arrayTitle->setDefaultTextColor(QColor(60, 75, 95));
    m_arrayTitle->setPos(kArrayLeft - 30, kArrayY - 30);

    m_phaseText = scene->addText("阶段一：把频率数组升序排序");
    m_phaseText->setFont(UiFonts::cjk(13, true));
    m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
    m_phaseText->setPos(110, 66);

    m_noteText = scene->addText("");
    m_noteText->setFont(UiFonts::mixed(13, true));
    m_noteText->setDefaultTextColor(QColor(200, 110, 40));
    m_noteText->setPos(110, 786);

    m_resultText = scene->addText("");
    m_resultText->setFont(UiFonts::cjk(13, true));
    m_resultText->setDefaultTextColor(QColor(40, 140, 70));
    m_resultText->setPos(110, 822);

    m_ptrA = new PointerBlock("x", QColor(210, 80, 55));
    m_ptrA->setOpacity(0);
    m_ptrA->setDirection(PointerBlock::Down);
    m_ptrA->setShaftLength(22);
    m_ptrA->setAnchorOffset(PointerGeometry::aboveCell(kCellW, kCellH));
    m_ptrA->setLabelAtTail(6.0);
    scene->addItem(m_ptrA);

    m_ptrB = new PointerBlock("y", QColor(45, 130, 210));
    m_ptrB->setOpacity(0);
    m_ptrB->setDirection(PointerBlock::Down);
    m_ptrB->setShaftLength(22);
    m_ptrB->setAnchorOffset(PointerGeometry::aboveCell(kCellW, kCellH));
    m_ptrB->setLabelAtTail(6.0);
    scene->addItem(m_ptrB);
}

std::vector<AnimFrame> HuffmanTreeModule::runAlgorithm() {
    m_frames.clear();
    if (!m_valid) return m_frames;

    const int leafCount = static_cast<int>(m_nodes.size());

    m_frames.push_back({ActionType::HF_RESET, 0, 0, 0, 0, {},
                        QString("频率数组 a[]：%1 个权值待排序").arg(leafCount),
                        QString("哈夫曼树 = 最优前缀编码树")});

    std::vector<long long> weights;
    for (const HuffNode& node : m_nodes) weights.push_back(node.weight);

    std::vector<int> state;
    for (int i = 0; i < leafCount; ++i) state.push_back(i);

    std::vector<int> target;
    for (int i = 0; i < leafCount; ++i) target.push_back(i);
    std::sort(target.begin(), target.end(), [this](int a, int b) {
        if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
        return a < b;
    });

    for (size_t k = 0; k < target.size(); ++k) {
        if (state[k] == target[k]) continue;
        m_frames.push_back({ActionType::HF_SORT_LIFT, static_cast<int>(k), state[k],
                            static_cast<int>(weights[state[k]]), 0, {target[k]},
                            QString("a[%1] = %2 不在排序后应在的位置，先飞出数组")
                                .arg(k).arg(weights[state[k]]),
                            QString("不在应有位置的元素先飞出")});
    }

    for (size_t k = 0; k < target.size(); ++k) {
        state[k] = target[k];
        m_frames.push_back({ActionType::HF_SORT_DROP, static_cast<int>(k), target[k],
                            static_cast<int>(weights[target[k]]), 0, state,
                            QString("a[%1] = %2 像流星一样飞回第 %3 个位置")
                                .arg(k).arg(weights[target[k]]).arg(k),
                            QString("飞星落位")});
    }

    QStringList sortedText;
    for (int id : target) sortedText << QString::number(m_nodes[id].weight);
    m_frames.push_back({ActionType::HF_SORT_DONE, 0, 0, 0, 0, {},
                        QString("频率数组排序完成：%1").arg(sortedText.join(" < ")),
                        QString("阶段一完成，进入建树阶段")});

    m_frames.push_back({ActionType::HF_RESET, 1, 0, 0, 0, {},
                        QString("阶段二：开始建树，每次从数组中取两个最小权值"),
                        QString("阶段二：建树")});

    computePlan();

    for (size_t s = 0; s < m_plan.size(); ++s) {
        const MergeStep& step = m_plan[s];
        const QString kindText = step.kind == 0
                                     ? "两个都是原始数据，直接作为叶子连到父节点"
                                     : (step.kind == 1 ? "其中一个已带子树，让另一个飞过去与它相连"
                                                        : "两个都带子树，先把树高调整到同一行再相连");

        m_frames.push_back({ActionType::HF_PICK, step.a, step.b,
                            static_cast<int>(m_nodes[step.a].weight),
                            static_cast<int>(m_nodes[step.b].weight), {step.kind},
                            QString("取出两个最小权值：%1（%2）与 %3（%4）；%5")
                                .arg(step.a).arg(m_nodes[step.a].weight)
                                .arg(step.b).arg(m_nodes[step.b].weight).arg(kindText),
                            QString("每次取两个最小")});

        m_frames.push_back({ActionType::HF_LIFT, step.a, step.b,
                            static_cast<int>(m_nodes[step.a].weight),
                            static_cast<int>(m_nodes[step.b].weight), {step.kind},
                            step.kind == 0
                                ? QString("%1 与 %2 一起飞向汇合点，准备作为叶子连接")
                                    .arg(m_nodes[step.a].weight).arg(m_nodes[step.b].weight)
                                : QString("带子树的一方上移到同一行，准备与 %1 相连")
                                    .arg(m_nodes[step.b].weight),
                            QString("飞到一起")});

        m_frames.push_back({ActionType::HF_MERGE, step.a, step.b, step.parent,
                            static_cast<int>(m_nodes[step.parent].weight), {step.kind},
                            QString("合并成新节点 %1：%2 + %3 = %4")
                                .arg(step.parent).arg(m_nodes[step.a].weight)
                                .arg(m_nodes[step.b].weight).arg(m_nodes[step.parent].weight),
                            QString("新节点权值 = 左 + 右")});
    }

    const int rootId = m_plan.empty() ? 0 : m_plan.back().parent;
    m_frames.push_back({ActionType::HF_DONE, rootId, static_cast<int>(m_nodes.size()), 0, 0, {},
                        QString("哈夫曼树构造完成：共 %1 个节点，根节点权值 = %2")
                            .arg(m_nodes.size()).arg(m_nodes[rootId].weight),
                        QString("带权路径长度最小 = 最优前缀编码")});
    return m_frames;
}

void HuffmanTreeModule::renderFrame(const AnimFrame& frame) {
    if (m_mathText) {
        m_mathText->setPlainText(frame.mathText.isEmpty() ? frame.explanation : frame.mathText);
    }
    if (!m_valid) return;

    if (frame.type == ActionType::HF_RESET) {
        m_phaseTwo = frame.u == 1;
        m_usedCount = 0;
        for (auto& kv : m_treeNodes) {
            if (!kv.second) continue;
            const HuffNode* node = nodeAt(kv.first);
            kv.second->color = (node && node->original) ? kHfLeaf : kHfMerge;
            kv.second->setHighlightColor(Qt::transparent);
            kv.second->update();
        }
        for (auto& kv : m_childEdges) {
            kv.second->setColor(kHfEdge);
            kv.second->setPenWidth(2.0);
            kv.second->update();
        }
        refreshArrayColors();
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText("");
            m_noteText->setDefaultTextColor(QColor(200, 110, 40));
        }
        if (m_resultText) m_resultText->setPlainText("");
        if (m_phaseTwo) {
            m_phaseText->setPlainText("阶段二：每次从数组中取两个最小权值合并建树");
            m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
        } else {
            m_phaseText->setPlainText("阶段一：把频率数组升序排序");
            m_phaseText->setDefaultTextColor(QColor(70, 110, 170));
        }
        return;
    }

    if (frame.type == ActionType::HF_SORT_LIFT) {
        const int slot = frame.u;
        ArrayBlock* cell = (slot >= 0 && slot < static_cast<int>(m_arrayCells.size()))
                               ? m_arrayCells[slot] : nullptr;
        if (cell) {
            cell->color = kHfPick;
            cell->update();
            if (m_animated) playScalePulse(cell, 1.18, 240);
        }
        if (m_ptrA && cell) {
            m_ptrA->setOpacity(1);
            retargetPointerTo(m_ptrA, cell, PointerGeometry::aboveCell(kCellW, kCellH));
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_SORT_DROP) {
        const int slot = frame.u;
        const int nodeId = frame.v;
        const std::vector<int>& perm = frame.group;
        if (perm.size() != m_arrayCells.size()) return;

        for (size_t i = 0; i < perm.size(); ++i) {
            ArrayBlock* cell = m_arrayCells[i];
            const int id = perm[i];
            if (id >= 0 && id < static_cast<int>(m_nodes.size())) {
                cell->setCustomValue(QString::number(m_nodes[id].weight));
            }
            cell->color = (static_cast<int>(i) == slot) ? kHfSorted : kHfLeaf;
            cell->update();
        }

        ArrayBlock* dest = (slot >= 0 && slot < static_cast<int>(m_arrayCells.size()))
                               ? m_arrayCells[slot] : nullptr;
        if (dest && m_animated) {
            const QPointF start = QPointF(dest->pos().x() + kCellW / 2.0, kArrayY - 80.0);
            const long long weight = (nodeId >= 0 && nodeId < static_cast<int>(m_nodes.size()))
                                         ? m_nodes[nodeId].weight : 0;
            playBubbleFlight(start, dest->pos(), static_cast<int>(weight), 520);
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_SORT_DONE) {
        for (auto* cell : m_arrayCells) {
            cell->color = kHfSorted;
            cell->update();
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(40, 140, 70));
        }
        return;
    }

    if (frame.type == ActionType::HF_PICK) {
        const int a = frame.u;
        const int b = frame.v;
        HuffNode* na = nodeAt(a);
        HuffNode* nb = nodeAt(b);
        if (na && na->item) {
            na->item->color = kHfPick;
            na->item->setHighlightColor(kHfPick);
            na->item->update();
            if (m_animated) playScalePulse(na->item, 1.16, 240);
        }
        if (nb && nb->item) {
            nb->item->color = kHfPick;
            nb->item->setHighlightColor(kHfPick);
            nb->item->update();
            if (m_animated) playScalePulse(nb->item, 1.16, 240);
        }
        if (m_ptrA && na && na->item) {
            m_ptrA->setOpacity(1);
            retargetPointerTo(m_ptrA, na->item, QPointF(0.0, -(kNodeR + 30.0)));
        }
        if (m_ptrB && nb && nb->item) {
            m_ptrB->setOpacity(1);
            retargetPointerTo(m_ptrB, nb->item, QPointF(0.0, -(kNodeR + 30.0)));
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_LIFT) {
        const int a = frame.u;
        const int b = frame.v;
        HuffNode* na = nodeAt(a);
        HuffNode* nb = nodeAt(b);
        if (na && na->item) {
            na->item->setHighlightColor(kHfPick);
            na->item->update();
            if (m_animated) playScalePulse(na->item, 1.24, 320);
        }
        if (nb && nb->item) {
            nb->item->setHighlightColor(kHfPick);
            nb->item->update();
            if (m_animated) playScalePulse(nb->item, 1.24, 320);
        }
        if (m_noteText) m_noteText->setPlainText(frame.explanation);
        return;
    }

    if (frame.type == ActionType::HF_MERGE) {
        const int a = frame.u;
        const int b = frame.v;
        const int parentId = frame.val1;

        HuffNode* parent = nodeAt(parentId);
        if (parent && !parent->item) {
            GraphNode* item = new GraphNode(parentId);
            item->color = kHfMerge;
            item->setCustomValueText(QString::number(frame.val2));
            m_scene->addItem(item);
            parent->item = item;
            m_treeNodes[parentId] = item;
        }
        if (parent && parent->item) {
            parent->item->setCustomValueText(QString::number(frame.val2));
            parent->item->color = kHfMerge;
            parent->item->setHighlightColor(kHfMerge);
            parent->item->update();
        }

        auto makeEdge = [&](int childId, int key) {
            if (m_childEdges.count(key)) return;
            HuffNode* child = nodeAt(childId);
            if (!child || !child->item || !parent || !parent->item) return;
            GraphEdge* edge = new GraphEdge(child->item, parent->item, true);
            edge->setColor(kHfEdgeNew);
            edge->setPenWidth(2.6);
            m_scene->addItem(edge);
            child->item->addEdge(edge);
            parent->item->addEdge(edge);
            m_childEdges[key] = edge;
        };
        makeEdge(a, parentId * 2);
        makeEdge(b, parentId * 2 + 1);

        applyMergeRows(a, b, parentId);
        computePositions();
        applyPositions(m_animated ? 460 : 0);

        m_usedCount = qMin(m_usedCount + 1, static_cast<int>(m_arrayCells.size()));
        refreshArrayColors();

        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        if (m_noteText) {
            m_noteText->setPlainText(frame.explanation);
            m_noteText->setDefaultTextColor(QColor(70, 110, 170));
        }
        return;
    }

    if (frame.type == ActionType::HF_DONE) {
        const int rootId = frame.u;
        auto it = m_treeNodes.find(rootId);
        if (it != m_treeNodes.end() && it->second) {
            it->second->color = kHfRoot;
            it->second->setHighlightColor(kHfRoot);
            it->second->update();
            if (m_animated) playScalePulse(it->second, 1.26, 340);
        }
        if (m_ptrA) m_ptrA->setOpacity(0);
        if (m_ptrB) m_ptrB->setOpacity(0);
        m_phaseText->setPlainText("阶段二完成：哈夫曼树构造结束");
        m_phaseText->setDefaultTextColor(QColor(40, 140, 70));
        if (m_resultText) {
            m_resultText->setPlainText(frame.explanation);
            m_resultText->setDefaultTextColor(QColor(40, 140, 70));
        }
    }
}

void HuffmanTreeModule::reset() {
    m_frames.clear();
    m_nodes.clear();
    m_plan.clear();
    m_leafOrder.clear();
    m_arrayCells.clear();
    m_treeNodes.clear();
    m_childEdges.clear();
    m_targets.clear();
    m_mathText = nullptr;
