void HuffmanTreeModule::applyMergeRows(int a, int b, int parent) {
    HuffNode* pa = nodeAt(a);
    HuffNode* pb = nodeAt(b);
    HuffNode* pp = nodeAt(parent);
    if (!pa || !pb || !pp) return;

    const int baseRow = qMax(pa->row, pb->row);
    if (pa->row != pb->row) {
        const int lower = qMin(pa->row, pb->row);
        const int upper = qMax(pa->row, pb->row);
        HuffNode* lowNode = (pa->row == lower) ? pa : pb;
        HuffNode* highNode = (pa->row == lower) ? pb : pa;
        const int delta = upper - lower;
        shiftSubtreeRows(highNode->id, delta);
        shiftSubtreeRows(lowNode->id, delta);
    }
    pa->row = baseRow + 1;
    pb->row = baseRow + 1;
    pp->row = baseRow;
}

