void HuffmanTreeModule::computePlan() {
    m_plan.clear();
    std::vector<int> alive;
    for (int i = 0; i < static_cast<int>(m_nodes.size()); ++i) alive.push_back(i);

    while (alive.size() > 1) {
        std::sort(alive.begin(), alive.end(), [this](int a, int b) {
            if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
            return a < b;
        });
        const int a = alive[0];
        const int b = alive[1];
        const bool aOriginal = m_nodes[a].original;
        const bool bOriginal = m_nodes[b].original;
        const int kind = (aOriginal && bOriginal) ? 0 : ((aOriginal != bOriginal) ? 1 : 2);

        HuffNode parent;
        parent.id = static_cast<int>(m_nodes.size());
        parent.weight = m_nodes[a].weight + m_nodes[b].weight;
        parent.left = a;
        parent.right = b;
        parent.original = false;
        m_nodes.push_back(parent);
        m_nodes[a].parent = parent.id;
        m_nodes[b].parent = parent.id;

        const int baseRow = qMax(m_nodes[a].row, m_nodes[b].row);
        if (m_nodes[a].row != m_nodes[b].row) {
            const int lower = qMin(m_nodes[a].row, m_nodes[b].row);
            const int delta = baseRow - lower;
            const int lowId = (m_nodes[a].row == lower) ? a : b;
            const int highId = (m_nodes[a].row == lower) ? b : a;
            shiftSubtreeRows(highId, delta);
            shiftSubtreeRows(lowId, delta);
        }
        m_nodes[a].row = baseRow + 1;
        m_nodes[b].row = baseRow + 1;
        m_nodes[parent.id].row = baseRow;

        MergeStep step;
        step.a = a;
        step.b = b;
        step.parent = parent.id;
        step.kind = kind;
        m_plan.push_back(step);

        alive.erase(alive.begin(), alive.begin() + 2);
        alive.push_back(parent.id);
    }
}

