void HuffmanTreeModule::computePositions(const std::map<int, int>& rows, const std::map<int, int>& cols,
                                         std::map<int, QPointF>& out) const {
    out.clear();
    const int count = static_cast<int>(m_nodes.size());
    if (count == 0) return;

    const double leafSpan = kBaseGap;
    const double width = qMax(1, static_cast<int>(m_sortedLeaves.size())) * leafSpan;
    const double left = kTreeCenterX - width / 2.0 + leafSpan / 2.0;

    std::map<int, int> leafIndex;
    for (size_t k = 0; k < m_sortedLeaves.size(); ++k) {
        leafIndex[m_sortedLeaves[k]] = static_cast<int>(k);
    }

    std::map<int, double> xOf;
    for (const auto& kv : leafIndex) {
        xOf[kv.first] = left + kv.second * leafSpan;
    }

    for (int id = 0; id < count; ++id) {
        if (m_nodes[id].original) continue;
        const HuffmanNodeData* node = nodeAt(id);
        const int l = node->left;
        const int r = node->right;
        const double lx = (l >= 0 && xOf.count(l)) ? xOf.at(l) : left;
        const double rx = (r >= 0 && xOf.count(r)) ? xOf.at(r) : left;
        xOf[id] = (lx + rx) / 2.0;
    }

    for (int id = 0; id < count; ++id) {
        const int row = rows.count(id) ? rows.at(id) : 0;
