    std::vector<int> leaves;
    for (int i = 0; i < count; ++i) {
        if (m_nodes[i].original) leaves.push_back(i);
    }
    std::sort(leaves.begin(), leaves.end(), [this](int a, int b) {
        if (m_nodes[a].weight != m_nodes[b].weight) return m_nodes[a].weight < m_nodes[b].weight;
        return a < b;
    });
    m_sortedLeaves = leaves;

    std::map<int, int> leafCol;
    for (size_t k = 0; k < leaves.size(); ++k) {
        leafCol[leaves[k]] = static_cast<int>(k);
    }

    auto buildRows = [&](const std::vector<int>& forest, std::map<int, int>& rows) {
        rows.clear();
        std::map<int, int> relDepth;
        int maxRel = 0;
        for (int root : forest) {
            std::vector<std::pair<int, int>> stack;
            stack.push_back({root, 0});
            while (!stack.empty()) {
                const int id = stack.back().first;
                const int d = stack.back().second;
                stack.pop_back();
                relDepth[id] = d;
                maxRel = qMax(maxRel, d);
                const HuffmanNodeData* node = nodeAt(id);
                if (!node) continue;
                if (node->left >= 0) stack.push_back({node->left, d + 1});
                if (node->right >= 0) stack.push_back({node->right, d + 1});
            }
        }
        for (const auto& kv : relDepth) {
            rows[kv.first] = maxRel - kv.second;
        }
    };

    std::vector<int> forest;
    for (int i = 0; i < m_leafCount; ++i) forest.push_back(i);

    std::map<int, int> rows;
    std::map<int, int> cols;
    buildRows(forest, rows);

    for (size_t s = 0; s < m_plan.size(); ++s) {
        HuffmanMergeStep& step = m_plan[s];
        const int a = step.a;
        const int b = step.b;
        const int parent = step.parent;

        step.liftRows = rows;
        step.liftCols = cols;

        std::vector<int> nextForest = forest;
        nextForest.erase(std::remove(nextForest.begin(), nextForest.end(), a), nextForest.end());
        nextForest.erase(std::remove(nextForest.begin(), nextForest.end(), b), nextForest.end());
        nextForest.push_back(parent);

        buildRows(nextForest, rows);
        step.rows = rows;
        step.cols = cols;

        forest = nextForest;
    }
}

