#ifndef HUFFMANTREEMODULE_H
#define HUFFMANTREEMODULE_H
#include "IModule.h"
#include "render/GraphElements.h"
#include <QObject>
#include <QGraphicsTextItem>
#include <map>
#include <vector>

struct HuffmanNodeData {
    int id = 0;
    long long weight = 0;
    int left = -1;
    int right = -1;
    int parent = -1;
    bool original = true;
    GraphNode* item = nullptr;
};

struct HuffmanMergeStep {
    int a = 0;
    int b = 0;
    int parent = 0;
    int kind = 0;
    std::map<int, int> liftRows;
    std::map<int, int> liftCols;
    std::map<int, int> rows;
    std::map<int, int> cols;
};

struct HuffmanCodeRow {
    int leafId = 0;
    int originalIndex = 0;
    long long weight = 0;
    QString code;
    int codeLength = 0;
};

class HuffmanTreeModule : public QObject, public IModule {
    Q_OBJECT
public:
    HuffmanTreeModule();
    QString getModuleName() const override;
    QString getDefaultInput() const override;
    QString getInputHint() const override;
    void buildLayout(QGraphicsScene* scene, const QString& inputData) override;
    std::vector<AnimFrame> runAlgorithm() override;
    void renderFrame(const AnimFrame& frame) override;
    void reset() override;
    void releaseSceneItems() override;

private:
    static constexpr double kNodeR = 21.0;
    static constexpr double kCellW = 76.0;
    static constexpr double kCellH = 44.0;
    static constexpr double kArrayY = 150.0;
    static constexpr double kArrayLeft = 150.0;
    static constexpr double kTreeTop = 300.0;
    static constexpr double kLevelH = 84.0;
    static constexpr double kBaseGap = 104.0;
    static constexpr double kTreeCenterX = 350.0;
    static constexpr double kTableX = 640.0;
    static constexpr double kTableCellW = 78.0;
    static constexpr double kTableCellH = 38.0;
    static constexpr double kTableTop = 300.0;
    static constexpr double kWplY = 700.0;

    HuffmanNodeData* nodeAt(int id);
    const HuffmanNodeData* nodeAt(int id) const;
    void computeTree();
    void simulateLayout();
    void computePositions(const std::map<int, int>& rows, const std::map<int, int>& cols,
                          std::map<int, QPointF>& out) const;
    void applyPositions(const std::map<int, QPointF>& positions, int duration);
    void refreshArrayColors(int used);
    void computeCodes();
    void buildCodeTable();
    void resetCodeTable();
    void refreshCodeTableRow(int rowIndex);
    void updateWplRow(int rowIndex, long long product, long long running);

    std::vector<AnimFrame> m_frames;
    std::vector<HuffmanNodeData> m_nodes;
    std::vector<HuffmanMergeStep> m_plan;
    std::vector<int> m_sortedLeaves;
    std::vector<int> m_forest;
    std::vector<ArrayBlock*> m_arrayCells;
    std::vector<HuffmanCodeRow> m_codeRows;
    std::vector<ArrayBlock*> m_codeFreqCells;
    std::vector<ArrayBlock*> m_codeCells;
    std::vector<ArrayBlock*> m_codeLenCells;
    std::vector<ArrayBlock*> m_wplCells;
    std::map<int, GraphNode*> m_treeNodes;
    std::map<int, GraphEdge*> m_childEdges;

    QGraphicsTextItem* m_mathText = nullptr;
    QGraphicsTextItem* m_noteText = nullptr;
    QGraphicsTextItem* m_phaseText = nullptr;
    QGraphicsTextItem* m_resultText = nullptr;
    QGraphicsTextItem* m_arrayTitle = nullptr;
    QGraphicsTextItem* m_tableTitle = nullptr;
    QGraphicsTextItem* m_tableHeader = nullptr;
    QGraphicsTextItem* m_wplTitle = nullptr;
