        const HuffmanNodeData* node = nodeAt(cur);
        if (!node || node->original) break;
        const bool leftIsLeaf = (node->left >= 0) && m_nodes[node->left].original;
        const int key = node->id * 4 + (leftIsLeaf ? 0 : 1);
        auto it = m_childEdges.find(key);
        if (it != m_childEdges.end() && it->second) {
            it->second->setPathLabel(leftIsLeaf ? "0" : "1");
            it->second->setPathLabelColor(kHfPath);
            it->second->update();
        }
        cur = node->parent;
    }
}

