void HuffmanTreeModule::liftSubtree(int id, int delta, std::map<int, int>& rows) const {
    if (id < 0) return;
    auto it = rows.find(id);
    if (it != rows.end()) it->second += delta;
    const HuffmanNodeData* node = nodeAt(id);
    if (!node) return;
    liftSubtree(node->left, delta, rows);
    liftSubtree(node->right, delta, rows);
}

