double HuffmanTreeModule::subtreeWidth(int id, std::map<int, double>& memo) const {
    auto it = memo.find(id);
    if (it != memo.end()) return it->second;
    const HuffmanNodeData* node = nodeAt(id);
    if (!node) return 0.0;
    if (node->original) {
        memo[id] = kLeafSpan;
        return kLeafSpan;
    }
    const double lw = subtreeWidth(node->left, memo);
    const double rw = subtreeWidth(node->right, memo);
    const double w = qMax(lw + rw, kLeafSpan);
    memo[id] = w;
    return w;
}

void HuffmanTreeModule::layoutComponent(int id, double rootX, std::map<int, double>& xs,
                                        std::map<int, double>& memo) const {
    const HuffmanNodeData* node = nodeAt(id);
    if (!node) return;
    if (node->original) {
        xs[id] = rootX;
        return;
    }
    const double lw = subtreeWidth(node->left, memo);
    const double rw = subtreeWidth(node->right, memo);
    const double leftX = rootX - (lw - rw) / 2.0 - lw / 2.0;
    const double rightX = rootX + (rw - lw) / 2.0 + rw / 2.0;
    xs[id] = rootX;
    layoutComponent(node->left, leftX, xs, memo);
    layoutComponent(node->right, rightX, xs, memo);
}

