void HuffmanTreeModule::simulateStates() {
    m_states.clear();
    m_compRank.clear();
    int nextRank = 0;
    for (int id : m_sortedLeaves) m_compRank[id] = nextRank++;

    HuffmanSimState state;
    for (int i = 0; i < m_leafCount; ++i) {
        state.levels[i] = 0;
        state.inTree.insert(i);
        state.entries.push_back(i);
    }
    for (int id : m_sortedLeaves) state.queue.push_back(id);
    computeStateLayout(state);
    m_states.push_back(state);

    for (size_t s = 0; s < m_plan.size(); ++s) {
        HuffmanMergeStep& step = m_plan[s];
        const int a = step.a;
        const int b = step.b;

        const int aLevel = state.levels.count(a) ? state.levels.at(a) : 0;
        const int bLevel = state.levels.count(b) ? state.levels.at(b) : 0;
        step.promoted = -1;
        step.promoteDelta = 0;

        if (aLevel != bLevel) {
            const int lower = (aLevel < bLevel) ? a : b;
            const int higher = (aLevel < bLevel) ? b : a;
            const int delta = qAbs(aLevel - bLevel);
            liftSubtree(lower, delta, state.levels);
            step.promoted = lower;
            step.promoteDelta = delta;
            computeStateLayout(state);
            step.promo = state;
        }

        const int base = qMax(state.levels.count(a) ? state.levels.at(a) : 0,
                              state.levels.count(b) ? state.levels.at(b) : 0) + 1;
        state.levels[step.parent] = base;

        state.entries.erase(std::remove(state.entries.begin(), state.entries.end(), a), state.entries.end());
        state.entries.erase(std::remove(state.entries.begin(), state.entries.end(), b), state.entries.end());
        state.entries.push_back(step.parent);
        m_compRank[step.parent] = m_compRank.count(a) ? m_compRank[a] : nextRank++;
        computeStateLayout(state);
        step.mid = state;

        state.queue.erase(std::remove(state.queue.begin(), state.queue.end(), a), state.queue.end());
        state.queue.erase(std::remove(state.queue.begin(), state.queue.end(), b), state.queue.end());
        state.queue.push_back(step.parent);
        std::stable_sort(state.queue.begin(), state.queue.end(), [this](int x, int y) {
            if (m_nodes[x].weight != m_nodes[y].weight) return m_nodes[x].weight < m_nodes[y].weight;
            const bool xLeaf = m_nodes[x].original;
            const bool yLeaf = m_nodes[y].original;
            if (xLeaf != yLeaf) return xLeaf;
            return x < y;
        });
        step.after = state;
        m_states.push_back(state);
    }
}

