void HuffmanTreeModule::applyTreePositions(const HuffmanSimState& state, int duration) {
    std::vector<QGraphicsItem*> movers;
    std::vector<QPointF> goals;
    for (const auto& kv : state.xs) {
        auto it = m_treeNodes.find(kv.first);
        if (it == m_treeNodes.end() || !it->second) continue;
        const int lv = state.levels.count(kv.first) ? state.levels.at(kv.first) : 0;
        movers.push_back(it->second);
        goals.push_back(QPointF(kCenterX + kv.second, kTreeBottomY - lv * kLevelH));
    }
    if (movers.empty()) return;
    playMoveTo(movers, goals, duration);
}

void HuffmanTreeModule::syncTreeNodesToState(const HuffmanSimState& state) {
    for (const auto& kv : state.xs) {
        auto it = m_treeNodes.find(kv.first);
        if (it == m_treeNodes.end() || !it->second) continue;
        const int lv = state.levels.count(kv.first) ? state.levels.at(kv.first) : 0;
        it->second->setPos(QPointF(kCenterX + kv.second, kTreeBottomY - lv * kLevelH));
    }
}

void HuffmanTreeModule::revealEdgesFor(int parentId) {
    for (int key : {parentId * 4 + 0, parentId * 4 + 1}) {
        auto it = m_childEdges.find(key);
        if (it == m_childEdges.end() || !it->second) continue;
        it->second->setOpacity(1.0);
        it->second->setColor(kHfEdgeNew);
        it->second->setPenWidth(2.6);
        it->second->update();
    }
}

