#include "modules/HuffmanTreeModule.h"
#include <QApplication>
#include <QGraphicsScene>
#include <QGraphicsTextItem>
#include <cstdio>

static void dumpScene(QGraphicsScene* scene, const char* tag) {
    printf("--- %s ---\n", tag);
    for (QGraphicsItem* item : scene->items()) {
        GraphNode* n = dynamic_cast<GraphNode*>(item);
        if (!n) continue;
        if (n->id >= 5000) continue;
        printf("node id=%d val='%s' pos=(%.1f,%.1f)\n", n->id,
               n->customValueText.toUtf8().constData(), n->pos().x(), n->pos().y());
    }
}

int main(int argc, char** argv) {
    setvbuf(stdout, nullptr, _IONBF, 0);
    QApplication app(argc, argv);

    const char* inputs[] = {
        "7\n45 13 20 16 9 12 5",
        "8\n40 8 15 22 3 12 7 18",
        "5\n10 20 30 40 50",
        "6\n1 2 3 4 5 6"
    };

    for (const char* input : inputs) {
        QGraphicsScene scene;
        HuffmanTreeModule m;
        m.buildLayout(&scene, input);
        auto frames = m.runAlgorithm();
        printf("=== input %s frames=%d ===\n", input, (int)frames.size());
        for (auto& f : frames) m.renderFrame(f);
        dumpScene(&scene, "final");

        double minDist = 1e18;
        QList<QPair<QPointF, int>> pts;
        for (QGraphicsItem* item : scene.items()) {
            GraphNode* n = dynamic_cast<GraphNode*>(item);
            if (!n || n->id >= 5000) continue;
            if (n->opacity() < 0.5) continue;
            pts.append({n->pos(), n->id});
        }
        for (int i = 0; i < pts.size(); ++i) {
            for (int j = i + 1; j < pts.size(); ++j) {
                const double dx = pts[i].first.x() - pts[j].first.x();
                const double dy = pts[i].first.y() - pts[j].first.y();
                const double d = dx * dx + dy * dy;
                if (d < minDist) minDist = d;
            }
        }
        printf("min pairwise distance = %.2f\n", minDist > 1e17 ? -1.0 : minDist);
    }
    return 0;
}

#include "modules/HuffmanTreeModule.h"
#include <QApplication>
#include <QGraphicsScene>
#include <QGraphicsTextItem>
#include <cstdio>

int main(int argc, char** argv) {
    setvbuf(stdout, nullptr, _IONBF, 0);
    QApplication app(argc, argv);

    const char* inputs[] = {
        "7\n45 13 20 16 9 12 5",
        "8\n40 8 15 22 3 12 7 18",
        "5\n10 20 30 40 50",
        "6\n1 2 3 4 5 6",
        "4\n5 5 5 5",
        "2\n7 9"
    };

    bool allOk = true;
    for (const char* input : inputs) {
        QGraphicsScene scene;
        HuffmanTreeModule m;
        m.m_animated = false;
        m.buildLayout(&scene, input);
        auto frames = m.runAlgorithm();
        for (auto& f : frames) m.renderFrame(f);

        std::map<int, QPointF> tree;
        for (QGraphicsItem* item : scene.items()) {
            GraphNode* n = dynamic_cast<GraphNode*>(item);
            if (!n || n->id >= 5000) continue;
            if (n->opacity() < 0.5) continue;
            if (n->pos().y() > 600.0) continue;
            tree[n->id] = n->pos();
        }
        printf("=== %s : frames=%d treeNodes=%d ===\n", input, (int)frames.size(), (int)tree.size());
        for (const auto& kv : tree) {
            printf("  node %d at (%.1f, %.1f)\n", kv.first, kv.second.x(), kv.second.y());
        }

        int midBad = 0;
        for (const auto& kv : tree) {
            const int id = kv.first;
            const HuffmanNodeData* n = m.nodeAt(id);
            if (!n || n->original) continue;
            auto li = tree.find(n->left);
            auto ri = tree.find(n->right);
            if (li == tree.end() || ri == tree.end()) continue;
            const double mid = (li->second.x() + ri->second.x()) / 2.0;
            const double err = qAbs(mid - kv.second.x());
            if (err > 0.6) {
                printf("  !! MIDPOINT VIOLATION node %d x=%.1f mid=%.1f err=%.2f\n", id, kv.second.x(), mid, err);
                midBad++;
            }
        }

        double minDist = 1e18;
        QList<QPointF> pts;
        for (const auto& kv : tree) pts.append(kv.second);
        for (int i = 0; i < pts.size(); ++i) {
            for (int j = i + 1; j < pts.size(); ++j) {
                const double dx = pts[i].x() - pts[j].x();
                const double dy = pts[i].y() - pts[j].y();
                const double d = dx * dx + dy * dy;
                if (d < minDist) minDist = d;
            }
        }
        const double minSep = minDist > 1e17 ? -1.0 : qSqrt(minDist);
        printf("  midpoint violations=%d  min node separation=%.2f\n", midBad, minSep);
        if (midBad > 0) allOk = false;
        if (minSep >= 0.0 && minSep < 44.0) { printf("  !! NODES TOO CLOSE\n"); allOk = false; }
    }
    printf("%s\n", allOk ? "ALL PASS" : "FAIL");
    return allOk ? 0 : 1;
}

#include "modules/HuffmanTreeModule.h"
#include <QApplication>
#include <QGraphicsScene>
#include <QGraphicsTextItem>
#include <cstdio>

int main(int argc, char** argv) {
    setvbuf(stdout, nullptr, _IONBF, 0);
    QApplication app(argc, argv);

    const char* inputs[] = {
        "7\n45 13 20 16 9 12 5",
        "8\n40 8 15 22 3 12 7 18",
        "5\n10 20 30 40 50",
        "6\n1 2 3 4 5 6",
        "4\n5 5 5 5",
        "2\n7 9"
    };

    bool allOk = true;
    for (const char* input : inputs) {
        QGraphicsScene scene;
        HuffmanTreeModule m;
        m.m_animated = false;
        m.buildLayout(&scene, input);
        auto frames = m.runAlgorithm();
        for (auto& f : frames) m.renderFrame(f);

        std::map<GraphNode*, QPointF> tree;
        std::map<GraphNode*, GraphNode*> parentOf;
        for (QGraphicsItem* item : scene.items()) {
            GraphNode* n = dynamic_cast<GraphNode*>(item);
            if (!n || n->id >= 5000) continue;
            if (n->opacity() < 0.5) continue;
            if (n->pos().y() > 600.0) continue;
            tree[n] = n->pos();
        }
        for (QGraphicsItem* item : scene.items()) {
            GraphEdge* e = dynamic_cast<GraphEdge*>(item);
            if (!e || !e->source || !e->dest) continue;
            if (!tree.count(e->source) || !tree.count(e->dest)) continue;
            parentOf[e->source] = e->dest;
        }

        printf("=== %s : frames=%d treeNodes=%d ===\n", input, (int)frames.size(), (int)tree.size());
        for (const auto& kv : tree) {
            printf("  node %d at (%.1f, %.1f)\n", kv.first->id, kv.second.x(), kv.second.y());
        }

        int midBad = 0;
        for (const auto& kv : tree) {
            GraphNode* child = kv.first;
            GraphNode* parent = parentOf.value(child, nullptr);
            if (!parent) continue;
            GraphNode* sibling = nullptr;
            for (const auto& kv2 : parentOf) {
                if (kv2.second == parent && kv2.first != child) sibling = kv2.first;
            }
            if (!sibling) continue;
            const double mid = (tree[child].x() + tree[sibling].x()) / 2.0;
            const double err = qAbs(mid - tree[parent].x());
            if (err > 0.6) {
                printf("  !! MIDPOINT VIOLATION parent %d x=%.1f mid=%.1f err=%.2f\n",
                       parent->id, tree[parent].x(), mid, err);
                midBad++;
            }
        }

        double minDist = 1e18;
        QList<QPointF> pts;
        for (const auto& kv : tree) pts.append(kv.second);
        for (int i = 0; i < pts.size(); ++i) {
            for (int j = i + 1; j < pts.size(); ++j) {
                const double dx = pts[i].x() - pts[j].x();
                const double dy = pts[i].y() - pts[j].y();
                const double d = dx * dx + dy * dy;
                if (d < minDist) minDist = d;
            }
        }
        const double minSep = minDist > 1e17 ? -1.0 : qSqrt(minDist);
        printf("  midpoint violations=%d  min node separation=%.2f\n", midBad, minSep);
        if (midBad > 0) allOk = false;
        if (minSep >= 0.0 && minSep < 44.0) { printf("  !! NODES TOO CLOSE\n"); allOk = false; }
    }
    printf("%s\n", allOk ? "ALL PASS" : "FAIL");
    return allOk ? 0 : 1;
}

