HuffmanLayoutInfo HuffmanTreeModule::subtreeLayout(int id, std::map<int, HuffmanLayoutInfo>& memo) const {
    auto it = memo.find(id);
    if (it != memo.end()) return it->second;
    const HuffmanNodeData* node = nodeAt(id);
    if (!node) return HuffmanLayoutInfo();
    if (node->original) {
        const HuffmanLayoutInfo info{HuffmanExtent{-kLeafSpan / 2.0, kLeafSpan / 2.0}, 0.0, 0.0};
        memo[id] = info;
        return info;
    }
    const HuffmanLayoutInfo li = subtreeLayout(node->left, memo);
    const HuffmanLayoutInfo ri = subtreeLayout(node->right, memo);
    const double half = kLeafSpan / 2.0;
    const double need = qMax(li.leftOffset, half) + qMax(ri.rightOffset, half) + kTreeGap;
    const double d = need / 2.0;
    const double leftOffset = -d;
    const double rightOffset = d;
    const double left = qMin(leftOffset + li.extent.left, rightOffset + ri.extent.left);
    const double right = qMax(leftOffset + li.extent.right, rightOffset + ri.extent.right);
    const HuffmanLayoutInfo info{HuffmanExtent{left, right}, leftOffset, rightOffset};
    memo[id] = info;
    return info;
}

